import{_ as o,o as r,c as s,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2019-06-25 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-06-25 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-06-25T00:00:00.000Z","updated":"2019-06-28T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","性能测试","代码审查"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-25_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-06-25_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),e={name:"posts/2019/2019-06-25_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function i(l,t,g,_,a,p){return r(),s("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年6月25日</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及问题讨论</p><p><strong>会议内容</strong>：</p><p><strong>1. CBT与SD测试进展</strong></p><ul><li><strong>问题</strong>： 开发人员在尝试使用商业SD卡进行CBT测试时遇到问题，Columbus大学的PG在激活后无法正常工作。</li><li><strong>解决方案</strong>： 通过替换Sam的sims更改尝试解决问题，但测试结果显示该功能仍然无法正常工作。</li><li><strong>后续行动</strong>： 开发人员将继续调查该问题，并寻找解决方案。</li></ul><p><strong>2. Crimson项目进展</strong></p><ul><li><strong>问题</strong>： 开发人员仍在尝试将Crimson与CBT更新兼容。</li><li><strong>解决方案</strong>： 开发人员已更新测试套件，并计划在下午重新运行测试。</li><li><strong>后续行动</strong>： Alfredo休假归来后，将与其他开发人员一起更新Crimson，使其与CBT兼容。</li></ul><p><strong>3. 性能测试</strong></p><ul><li><strong>问题</strong>： 需要部署性能测试并集成到RCI中，以便将最新的性能问题结果作为基准。</li><li><strong>解决方案</strong>： 将部署性能测试，并将其集成到RCI中。</li><li><strong>后续行动</strong>： 在合并之前，需要在本地运行性能测试，并将结果与PR一起发布。</li></ul><p><strong>4. 其他讨论</strong></p><ul><li><strong>PR审查</strong>： 开发人员讨论了如何快速构建系统以审查特定PR，并提出了使用Git工作区和get命令的建议。</li><li><strong>代码审查工具</strong>： 讨论了使用哪些工具来审查代码，并分享了使用GitHub和Git工作区的经验。</li></ul><p><strong>5. 行动计划</strong></p><ul><li>开发人员将继续调查CBT与SD测试的问题，并尝试找到解决方案。</li><li>开发人员将更新Crimson，使其与CBT兼容。</li><li>将部署性能测试并集成到RCI中。</li></ul><p><strong>会议总结</strong>：</p><p>本次会议讨论了Ceph分布式存储项目的进展和问题。开发人员将继续努力解决CBT与SD测试的问题，并更新Crimson项目。此外，还将部署性能测试并集成到RCI中。会议还涉及了PR审查和代码审查工具的讨论。</p>',17)])])}const m=o(e,[["render",i]]);export{S as __pageData,m as default};
